const root = $input.first().json || {};
const out = root.output ?? root.json ?? root;
return [{
  json: {
    intent: String(out.intent ?? root.intent ?? '').trim(),
    professional_id: out.professional_id ?? root.professional_id,
    service_id: out.service_id ?? root.service_id,
    appointment_date: out.appointment_date ?? out.date ?? root.appointment_date,
    customer_id: out.customer_id ?? root.enrichment?.customer_id ?? root.customer_id,
    response_text: String(out.response_text ?? root.response_text ?? ''),
    appointment_payload: out.appointment_payload ?? root.appointment_payload ?? {}
  }
}];
